# Kurs Motorsteuergerät · Modul 1–4
from common import *

M1 = {"id": "ecu.m1", "level": 1, "title": "Das Steuergerät im Überblick", "desc": "Aufgaben, Aufbau und Herzstück eines Motorsteuergeräts.", "lessons": [
 L("ecu.m1.l1", "Was ein Motorsteuergerät tut", 5, [
  "Das Motorsteuergerät (englisch ECU, Engine Control Unit) ist der Rechner, der den Verbrennungsmotor führt. Es liest Sensoren, berechnet in Millisekunden, wie viel Kraftstoff, Luft und Zündenergie der Motor gerade braucht, und steuert die Aktoren an.",
  "## Der Regelkreis",
  "Eingänge sind zum Beispiel Drehzahl und Kurbelwinkel, Luftmasse oder Saugrohrdruck, Fahrpedalstellung, Lambda-Werte und Temperaturen. Ausgänge sind Einspritzventile, Zündung, Drosselklappe, Nockenwellenversteller, Pumpen und Ventile. Dazwischen laufen hunderte Funktionen, viele davon im Takt der Kurbelwelle.",
  "## Mehr als nur Motor",
  "Moderne Steuergeräte überwachen sich selbst (Diagnose und OBD), tauschen über Busse Daten mit anderen Steuergeräten aus, schützen sich gegen Manipulation und erfüllen Abgas- sowie Sicherheitsvorschriften. Ein großer Teil der Software dient nicht dem Fahren, sondern dem Überwachen.",
  "Probiere unten das Blockschaltbild aus: Tippe auf die Bausteine."],
  ["ECU: liest Sensoren, berechnet, steuert Aktoren.", "Viele Funktionen laufen synchron zur Kurbelwelle.", "Ein großer Teil der Software ist Überwachung und Diagnose."],
  [S_REIF, S_KTB],
  [card("ECU (Engine Control Unit)", "Motorsteuergerät: Rechner, der Einspritzung, Zündung, Luftführung und weitere Motorfunktionen steuert."),
   card("Aktor", "Stellglied, das ein elektrisches Signal in eine Wirkung umsetzt, z. B. Einspritzventil oder Drosselklappe."),
   card("Sensor", "Messfühler, der eine physikalische Größe in ein elektrisches Signal umwandelt.")],
  [multi("Welche sind typische Eingänge eines Motorsteuergeräts?", ["Kurbelwellendrehzahl", "Fahrpedalstellung", "Ansteuerung der Einspritzventile", "Zündspulenansteuerung"], [0, 1], "Einspritzventile und Zündung sind Ausgänge (Aktoren)."),
   mc("Was ist ein Aktor?", ["Ein Stellglied, das etwas bewegt oder schaltet", "Ein Messfühler für Temperatur", "Ein Speicher für Fehlercodes", "Ein Bus für Daten"], 0, "Aktoren setzen Befehle des Steuergeräts in Wirkung um."),
   mc("Warum ist so viel Software im Steuergerät für Überwachung zuständig?", ["Abgas- und Sicherheitsvorschriften verlangen es", "Weil der Motor sonst nicht startet", "Weil Rechenzeit sonst ungenutzt bliebe", "Weil Sensoren nur so funktionieren"], 0, "OBD- und Sicherheitsanforderungen verlangen umfangreiche Selbstüberwachung."),
   mc("Welcher Wert wird typischerweise im Kurbelwellentakt berechnet?", ["Zündzeitpunkt", "Uhrzeit im Kombiinstrument", "Außentemperaturanzeige", "Radio-Lautstärke"], 0, "Zündung und Einspritzung müssen winkelgenau zum Motor erfolgen.")],
  figs=[{"after": 5, "w": "ecublock", "cap": "Blockschaltbild eines Motorsteuergeräts: Tippe auf einen Baustein."}]),
 L("ecu.m1.l2", "Der Mikrocontroller", 6, [
  "Herz des Steuergeräts ist ein Mikrocontroller, ein Chip mit Prozessorkernen, Speicher und Peripherie. In Motorsteuergeräten sind Mehrkern-Controller verbreitet, zum Beispiel aus der AURIX-Familie von Infineon.",
  "## Kerne und Lockstep",
  "Mehrere Kerne teilen sich die Arbeit, etwa schnelle winkelsynchrone Aufgaben, langsamere Zeitraster und Kommunikation. Für sicherheitsrelevante Software gibt es Lockstep-Kerne: Ein zweiter Kern rechnet dasselbe mit, und Abweichungen lösen eine Fehlerreaktion aus.",
  "## Speicher",
  "Der Programmcode und die Kalibrierdaten liegen im Flash-Speicher und bleiben ohne Strom erhalten. Variablen liegen im schnellen RAM. Lernwerte und Fehlerspeicher werden in nichtflüchtigen Bereichen gespeichert, oft als emuliertes EEPROM im Flash.",
  "## Peripherie",
  "Analog-Digital-Wandler (ADC) lesen Sensorspannungen, Timer-Module messen Zeiten und erzeugen Ansteuerpulse, Kommunikationsmodule sprechen CAN, FlexRay, LIN oder Ethernet. In AURIX-Controllern übernimmt das Generic Timer Module (GTM) unter anderem winkelbasierte Aufgaben. Ein Sicherheitsmodul (HSM) verwaltet Schlüssel für Secure Boot und verschlüsselte Kommunikation."],
  ["Mehrkern-Mikrocontroller mit Flash, RAM und Peripherie.", "Lockstep-Kerne prüfen sicherheitsrelevante Berechnungen.", "ADC, Timer, Busmodule und Sicherheitsmodul sind Teil des Chips."],
  [S_AURIX, S_GTM, S_REIF],
  [card("Mikrocontroller", "Chip mit Prozessorkern(en), Speicher und Peripherie auf einem Bauteil."),
   card("Lockstep", "Zwei Kerne rechnen parallel dasselbe; Abweichungen werden als Fehler erkannt."),
   card("Flash-Speicher", "Nichtflüchtiger Speicher für Programmcode und Kalibrierdaten."),
   card("HSM (Hardware Security Module)", "Geschützter Bereich im Controller für kryptografische Schlüssel und Funktionen, z. B. Secure Boot."),
   card("GTM (Generic Timer Module)", "Timer-Baustein von Bosch, u. a. in AURIX-Controllern; erzeugt und misst zeit- und winkelbasierte Signale.")],
  [mc("Wozu dienen Lockstep-Kerne?", ["Rechenfehler durch Vergleich erkennen", "Doppelte Rechenleistung für Spiele", "Strom sparen im Schlafmodus", "Daten auf CAN senden"], 0, "Beide Kerne berechnen dasselbe; Abweichungen deuten auf einen Hardwarefehler."),
   mc("Wo liegen Kalibrierdaten (Kennfelder, Kennlinien) typischerweise?", ["Im Flash-Speicher", "Im RAM", "Im ADC", "Im Lockstep-Kern"], 0, "Sie müssen ohne Strom erhalten bleiben."),
   mc("Was macht ein Analog-Digital-Wandler?", ["Wandelt Sensorspannungen in Zahlen um", "Schaltet Einspritzventile", "Speichert Fehlercodes", "Verschlüsselt Busnachrichten"], 0, "Der ADC macht analoge Spannungen für die Software lesbar."),
   mc("Welche Aufgabe hat ein HSM?", ["Schlüssel sicher verwalten", "Zündspulen laden", "Drehzahl messen", "Lambdawerte filtern"], 0, "Das Hardware Security Module schützt Schlüssel und kryptografische Funktionen.")]),
 L("ecu.m1.l3", "Spannungsversorgung und Klemmen", 6, [
  "Im Fahrzeug haben Stromanschlüsse feste Klemmennamen (nach DIN 72552). Klemme 30 ist Dauerplus von der Batterie, Klemme 31 ist Masse, Klemme 15 ist Plus bei eingeschalteter Zündung, Klemme 50 die Ansteuerung des Starters.",
  "## Was das Steuergerät daraus macht",
  "Spannungsregler erzeugen aus den 12 Volt des Bordnetzes stabile Spannungen für den Controller (zum Beispiel 5 V, 3,3 V und Kernspannungen) und eine Sensorversorgung. Für Direkteinspritzventile wird oft zusätzlich eine deutlich höhere Spannung erzeugt, weil sie sehr schnell öffnen müssen.",
  "## Belastungen",
  "Das Bordnetz ist rau: Beim Kaltstart kann die Spannung stark einbrechen, beim Abwerfen einer Last entstehen Spannungsspitzen. Das Steuergerät muss das überstehen, ohne Daten zu verlieren oder falsch zu schalten.",
  "## Überwachung",
  "Ein Watchdog prüft, ob die Software regelmäßig „lebt“. Bleibt das Signal aus, setzt er den Controller zurück oder schaltet in einen sicheren Zustand. In Motorsteuergeräten übernimmt oft ein eigener Überwachungsbaustein diese Rolle."],
  ["KL30 Dauerplus, KL31 Masse, KL15 Zündung, KL50 Starter.", "Regler erzeugen stabile Spannungen, teils auch Hochspannung für Injektoren.", "Watchdog: Software muss sich regelmäßig melden."],
  [S_KTB, S_REIF],
  [card("Klemme 30", "Dauerplus direkt von der Batterie."), card("Klemme 15", "Plus bei eingeschalteter Zündung."), card("Klemme 31", "Masse (Minus)."), card("Klemme 50", "Ansteuerung des Starters."),
   card("Watchdog", "Überwachung, die einen Reset oder sicheren Zustand auslöst, wenn die Software sich nicht rechtzeitig meldet.")],
  [mc("Welche Klemme liefert Dauerplus von der Batterie?", ["Klemme 30", "Klemme 15", "Klemme 31", "Klemme 50"], 0, "KL30 ist immer an, auch bei ausgeschalteter Zündung."),
   mc("Was signalisiert Klemme 15 dem Steuergerät?", ["Zündung ist eingeschaltet", "Der Starter dreht", "Die Batterie ist leer", "Das Fahrzeug ist verriegelt"], 0, "KL15 ist Plus bei eingeschalteter Zündung."),
   mc("Warum brauchen Direkteinspritzventile oft eine höhere Spannung?", ["Sie müssen sehr schnell öffnen", "Weil sie sonst rosten", "Weil die Batterie zu schwach ist", "Für die Diagnose"], 0, "Eine kurze Hochspannungsphase beschleunigt das Öffnen."),
   mc("Was tut ein Watchdog, wenn die Software nicht mehr reagiert?", ["Reset oder sicherer Zustand", "Er speichert die Uhrzeit", "Er erhöht die Drehzahl", "Nichts, er protokolliert nur"], 0, "Er verhindert, dass eine hängende Software weiter falsch steuert.")])
]}

M2 = {"id": "ecu.m2", "level": 1, "title": "Eingänge und Ausgänge", "desc": "Wie Sensorsignale ins Steuergerät kommen und wie Endstufen Aktoren schalten.", "lessons": [
 L("ecu.m2.l1", "Sensorsignale einlesen", 6, [
  "Sensoren liefern verschiedene Signalarten. Analoge Sensoren geben eine Spannung aus, zum Beispiel Temperatursensoren (oft als temperaturabhängiger Widerstand mit Spannungsteiler) oder Drucksensoren mit 0,5 bis 4,5 Volt. Digitale Sensoren schalten nur an und aus. Frequenz- oder pulsbasierte Sensoren kodieren den Wert in Zeiten, etwa Drehzahlsensoren.",
  "## Vom Pin zur Zahl",
  "Ein analoges Signal läuft über einen Eingangsfilter gegen Störungen und den Analog-Digital-Wandler. Die Software rechnet den Rohwert über eine Kennlinie in eine physikalische Größe um und filtert ihn weiter. Zeitbasierte Signale misst ein Timer-Modul mit hoher Auflösung.",
  "## Plausibilisieren",
  "Jeder Wert wird geprüft: Liegt die Spannung im gültigen Bereich? Ändert sich der Wert unrealistisch schnell? Passt er zu anderen Sensoren? Ein Drucksensor, der genau 0 V liefert, hat vermutlich einen Kurzschluss nach Masse, nicht null Druck. Deshalb nutzt man oft einen Messbereich, der die Ränder freilässt.",
  "## Sensorversorgung",
  "Viele Sensoren werden vom Steuergerät mit 5 V versorgt. Diese Versorgung wird überwacht, denn fällt sie aus, sind alle daran hängenden Werte falsch."],
  ["Signalarten: analog, digital, zeit- oder frequenzbasiert.", "Pin → Filter → ADC → Kennlinie → physikalischer Wert.", "Jeder Wert wird auf Bereich, Änderung und Plausibilität geprüft."],
  [S_REIF, S_KTB],
  [card("Kennlinie", "Zuordnung von Rohwert (z. B. Spannung) zu physikalischer Größe (z. B. Druck)."),
   card("Signal-Range-Check", "Prüfung, ob ein Sensorsignal im gültigen Spannungsbereich liegt; Werte außerhalb deuten auf Kurzschluss oder Unterbrechung."),
   card("Plausibilisierung", "Vergleich eines Messwerts mit anderen Größen oder Modellen, um Fehler zu erkennen.")],
  [mc("Ein Drucksensor mit Messbereich 0,5 bis 4,5 V liefert 0,05 V. Was ist am wahrscheinlichsten?", ["Kurzschluss nach Masse", "Ein extrem hoher Druck", "Ein normaler Leerlaufwert", "Ein Softwareupdate läuft"], 0, "Werte außerhalb des Messbereichs deuten auf einen elektrischen Fehler."),
   order("Bringe den Weg eines analogen Sensorsignals in die richtige Reihenfolge.", ["Sensor erzeugt Spannung", "Eingangsfilter", "Analog-Digital-Wandler", "Kennlinie in der Software", "Plausibilisierung und Weiterverarbeitung"], "So wird aus einer Spannung ein geprüfter physikalischer Wert."),
   mc("Warum lässt man bei Sensoren die Ränder des Spannungsbereichs (z. B. unter 0,5 V) frei?", ["Damit Kurzschlüsse erkennbar sind", "Um Strom zu sparen", "Weil der ADC dort nicht misst", "Damit der Sensor kühler bleibt"], 0, "So unterscheidet man echte Messwerte von Leitungsfehlern."),
   mc("Wie misst das Steuergerät ein drehzahlabhängiges Pulssignal?", ["Mit einem Timer über Zeitabstände", "Mit dem Watchdog", "Mit dem Flash-Speicher", "Gar nicht, nur über CAN"], 0, "Timer-Module messen die Zeit zwischen Flanken sehr genau.")]),
 L("ecu.m2.l2", "Endstufen: Aktoren schalten", 7, [
  "Die Ausgänge des Mikrocontrollers liefern nur winzige Ströme. Endstufen (Treiber) verstärken sie, um Ventile, Motoren und Relais zu schalten.",
  "## Low-Side und High-Side",
  "Ein Low-Side-Schalter verbindet den Verbraucher mit Masse, das Plus kommt dauerhaft von der Versorgung. Ein High-Side-Schalter schaltet das Plus. Low-Side ist einfacher und günstig; High-Side schützt besser, wenn eine Leitung gegen Masse scheuert, weil der Verbraucher dann nicht ungewollt anläuft.",
  "## H-Brücke",
  "Elektromotoren, die in beide Richtungen drehen müssen, etwa die elektrische Drosselklappe, werden über eine H-Brücke aus vier Schaltern angesteuert. Je nachdem, welches Paar schließt, fließt der Strom in die eine oder andere Richtung.",
  "## PWM",
  "Viele Aktoren werden mit Pulsweitenmodulation angesteuert: Der Schalter wird schnell ein- und ausgeschaltet; das Verhältnis von Ein- zu Gesamtzeit (Tastverhältnis) bestimmt die mittlere Leistung.",
  "## Spezielle Stufen",
  "Einspritzventile brauchen präzise Strom-Profile (kurzer Anzugsstrom, dann Haltestrom), Zündungen genaue Lade- und Zündzeitpunkte. Dafür gibt es spezialisierte Treiberbausteine, die mit dem Controller zusammenarbeiten."],
  ["Endstufen verstärken die Signale des Controllers.", "Low-Side schaltet Masse, High-Side schaltet Plus.", "H-Brücke für Motoren in zwei Richtungen; PWM für stufenlose Leistung."],
  [S_REIF, S_KTB],
  [card("Low-Side-Schalter", "Endstufe, die den Verbraucher zur Masse schaltet."),
   card("High-Side-Schalter", "Endstufe, die das Plus zum Verbraucher schaltet."),
   card("H-Brücke", "Vier Schalter, mit denen ein Motor in beide Richtungen angesteuert werden kann."),
   card("PWM (Pulsweitenmodulation)", "Schnelles Ein- und Ausschalten; das Tastverhältnis bestimmt die mittlere Leistung."),
   card("Anzugs- und Haltestrom", "Erst hoher Strom zum schnellen Öffnen eines Ventils, dann niedriger Strom zum Halten.")],
  [mc("Welche Schaltung braucht eine elektrische Drosselklappe, die in beide Richtungen stellen muss?", ["H-Brücke", "Einzelner Low-Side-Schalter", "Spannungsteiler", "ADC"], 0, "Nur eine H-Brücke kann die Stromrichtung umkehren."),
   num("Eine PWM hat 2 ms Einschaltzeit bei 10 ms Periode. Wie groß ist das Tastverhältnis in Prozent?", 20, "%", 0.1, "2 ÷ 10 = 0,2."),
   mc("Was schaltet ein Low-Side-Schalter?", ["Die Verbindung zur Masse", "Das Plus von der Batterie", "Die Busleitung", "Den Watchdog"], 0, "Der Verbraucher hängt dauerhaft an Plus, die Endstufe schaltet nach Masse."),
   mc("Warum bekommen Einspritzventile erst einen hohen, dann einen niedrigen Strom?", ["Schnell öffnen, dann sparsam halten", "Um die Batterie zu laden", "Damit das Ventil leiser ist", "Weil der Kraftstoff kalt ist"], 0, "Anzugsstrom öffnet schnell, Haltestrom vermeidet Überhitzung.")]),
 L("ecu.m2.l3", "Endstufen-Diagnose", 5, [
  "Das Steuergerät überwacht seine Ausgänge ständig. Typische Fehlerbilder sind Kurzschluss nach Masse, Kurzschluss nach Plus, Unterbrechung (Leitung oder Verbraucher offen) und Überlast oder Übertemperatur.",
  "## Wie Fehler erkannt werden",
  "Moderne Treiber messen Strom und Spannung an ihrem Ausgang. Ist der Schalter aus und die Spannung trotzdem niedrig, hängt die Leitung vermutlich an Masse. Ist er an und fließt kein Strom, ist der Kreis wohl offen. Bei zu hohem Strom schalten Treiber sich selbst ab, um nicht zu verbrennen.",
  "## Was danach passiert",
  "Der Fehler wird entprellt (er muss eine Zeit lang bestehen), dann im Fehlerspeicher eingetragen. Je nach Bauteil reagiert die Software mit einer Ersatzfunktion oder einem Notlauf, und bei abgasrelevanten Fehlern meldet sie ihn für die OBD."],
  ["Fehlerbilder: Kurzschluss nach Masse oder Plus, Unterbrechung, Überlast.", "Treiber messen Strom und Spannung zur Erkennung.", "Entprellen → Fehlerspeicher → Ersatzreaktion."],
  [S_REIF],
  [card("Unterbrechung (Open Load)", "Leitung oder Verbraucher ist offen; trotz eingeschalteter Endstufe fließt kein Strom."),
   card("Entprellung", "Ein Fehler muss eine definierte Zeit oder Anzahl bestehen, bevor er als bestätigt gilt.")],
  [mc("Die Endstufe ist eingeschaltet, aber es fließt kein Strom. Welcher Fehler liegt nahe?", ["Unterbrechung", "Kurzschluss nach Plus", "Übertemperatur", "Busfehler"], 0, "Ohne geschlossenen Kreis kann kein Strom fließen."),
   mc("Warum wird ein Fehler entprellt?", ["Um kurze Störungen nicht als Defekt zu werten", "Damit er schneller gemeldet wird", "Um Strom zu sparen", "Weil der Speicher zu klein ist"], 0, "Kurze Spitzen sollen keinen Fehlereintrag auslösen."),
   multi("Welche Fehler kann eine Endstufen-Diagnose typischerweise unterscheiden?", ["Kurzschluss nach Masse", "Unterbrechung", "Falsche Softwareversion", "Kurzschluss nach Plus"], [0, 1, 3], "Die Softwareversion hat mit der Endstufe nichts zu tun."),
   mc("Was tut ein Treiber bei starkem Überstrom?", ["Er schaltet sich selbst ab", "Er erhöht die Spannung", "Er löscht den Fehlerspeicher", "Er startet das Fahrzeug neu"], 0, "Selbstschutz verhindert die Zerstörung des Treibers.")])
]}

M3 = {"id": "ecu.m3", "level": 2, "title": "Betriebszustände", "desc": "Vom Wecken über Initialisierung und Betrieb bis Nachlauf, Schlaf, Notlauf und Programmiermodus.", "lessons": [
 L("ecu.m3.l1", "Der Lebenszyklus: Wecken bis Schlafen", 7, [
  "Ein Steuergerät ist nicht einfach an oder aus. Es durchläuft Zustände, die sauber gesteuert werden müssen, damit nichts verloren geht und die Batterie nicht leer wird.",
  "## Wecken",
  "Aus dem Schlaf (nur Klemme 30, minimale Stromaufnahme) wird das Steuergerät geweckt: durch Klemme 15, durch eine Busnachricht (Buswecken, z. B. beim Öffnen des Fahrzeugs) oder durch einen lokalen Weckeingang.",
  "## Initialisierung (Startup)",
  "Der Controller startet, prüft seinen Speicher, lädt Konfigurationen und Lernwerte, initialisiert Treiber und Kommunikation und testet Überwachungsfunktionen. Erst danach geht es in den Betrieb.",
  "## Betrieb (Run)",
  "Alle Funktionen laufen: Motorsteuerung, Diagnose, Kommunikation. Solange es Gründe zum Wachbleiben gibt (Zündung an, Busaktivität, laufende Funktionen), bleibt das Steuergerät hier.",
  "## Nachlauf (Post-Run)",
  "Nach dem Ausschalten der Zündung läuft das Steuergerät noch eine Weile weiter. Es speichert Lernwerte und Fehlerspeicher, lässt bei Bedarf Lüfter oder Pumpen nachlaufen und führt Diagnosen durch, die nur bei stehendem Motor möglich sind.",
  "## Herunterfahren und Schlaf",
  "Wenn niemand mehr das Steuergerät braucht, fährt es geordnet herunter und geht in den Schlaf. In AUTOSAR koordiniert das der ECU State Manager zusammen mit dem BSW Mode Manager; die genauen Zustandsnamen hängen von der Variante und dem Hersteller ab.",
  "Probiere den Zustandssimulator unten aus."],
  ["Schlaf → Wecken → Initialisierung → Betrieb → Nachlauf → Herunterfahren → Schlaf.", "Wecken über KL15, Bus oder lokalen Eingang.", "Im Nachlauf werden Lernwerte gespeichert und Nachlauffunktionen ausgeführt."],
  [S_AUTOSAR, S_REIF],
  [card("Nachlauf (Post-Run)", "Phase nach Zündung aus: Daten speichern, Lüfter/Pumpen nachlaufen lassen, Diagnosen ausführen."),
   card("Buswecken", "Wecken eines Steuergeräts über eine Nachricht auf dem Bus."),
   card("ECU State Manager (EcuM)", "AUTOSAR-Modul, das Start, Betrieb, Herunterfahren und Schlaf des Steuergeräts steuert."),
   card("Ruhestrom", "Sehr geringer Stromverbrauch im Schlaf, damit die Batterie nicht entladen wird.")],
  [order("Ordne die Zustände eines typischen Fahrzyklus.", ["Schlaf", "Initialisierung", "Betrieb", "Nachlauf", "Schlaf"], "Nach dem Nachlauf schläft das Steuergerät wieder ein."),
   mc("Warum gibt es einen Nachlauf nach dem Ausschalten der Zündung?", ["Um Lernwerte und Fehler zu speichern", "Damit der Motor weiterläuft", "Um das Radio zu betreiben", "Weil das Steuergerät langsam reagiert"], 0, "Daten müssen sicher im nichtflüchtigen Speicher landen; manche Diagnosen laufen nur bei stehendem Motor."),
   multi("Wodurch kann ein Steuergerät geweckt werden?", ["Klemme 15 ein", "Busnachricht", "Lokaler Weckeingang", "Klemme 31 aus"], [0, 1, 2], "Klemme 31 ist Masse und kein Wecksignal."),
   mc("Was passiert in der Initialisierung?", ["Speicher prüfen, Lernwerte laden, Treiber starten", "Fehlerspeicher löschen", "Die Batterie laden", "Das Fahrzeug entriegeln"], 0, "Erst nach erfolgreicher Initialisierung geht das Gerät in den Betrieb.")],
  figs=[{"after": 11, "w": "ecustate", "cap": "Zustandssimulator: Schalte Klemmen und Signale und beobachte den Zustand."}]),
 L("ecu.m3.l2", "Notlauf und sicherer Zustand", 6, [
  "Fällt eine wichtige Funktion aus, darf das Fahrzeug nicht unkontrolliert reagieren. Das Steuergerät schaltet dann in einen Notlauf oder in einen sicheren Zustand.",
  "## Ersatzwerte",
  "Fällt ein Sensor aus, rechnet die Software mit einem Ersatzwert oder Modell weiter. Fehlt etwa der Ansauglufttemperatursensor, nimmt sie einen festen Wert. Der Motor läuft, aber nicht optimal.",
  "## Leistungsbegrenzung",
  "Bei schwereren Fehlern wird die Leistung begrenzt, die Drehzahl beschränkt oder die Drosselklappe in eine Notlaufstellung gebracht. Der Fahrer kann so noch sicher weiterfahren oder anhalten (umgangssprachlich „Limp Home“).",
  "## Abschalten",
  "Kann eine sichere Funktion nicht mehr gewährleistet werden, etwa bei widersprüchlichen Fahrpedalsignalen, wird zum Beispiel die Momentanforderung auf Leerlauf begrenzt oder die Einspritzung abgeschaltet. Welcher Zustand „sicher“ ist, wird in der Sicherheitsanalyse festgelegt."],
  ["Sensorausfall → Ersatzwert oder Modell.", "Schwere Fehler → Leistung oder Drehzahl begrenzen.", "Der sichere Zustand ist in der Sicherheitsanalyse definiert."],
  [S_EGAS, S_26262],
  [card("Notlauf (Limp Home)", "Eingeschränkter Betrieb nach einem Fehler, der sicheres Weiterfahren oder Anhalten erlaubt."),
   card("Ersatzwert", "Fester oder berechneter Wert, mit dem die Software statt eines ausgefallenen Sensors rechnet."),
   card("Sicherer Zustand", "Zustand, in dem vom System keine unzulässige Gefahr ausgeht, z. B. Leerlaufmoment.")],
  [mc("Der Ansauglufttemperatursensor fällt aus. Was ist eine typische Reaktion?", ["Mit einem Ersatzwert weiterrechnen", "Motor sofort abstellen", "Fehlerspeicher löschen", "Drehzahl erhöhen"], 0, "Ein Ersatzwert hält den Motor betriebsbereit."),
   mc("Was ist bei widersprüchlichen Fahrpedalsignalen eine sinnvolle Reaktion?", ["Momentanforderung begrenzen", "Den höheren Wert nehmen", "Den Mittelwert verwenden", "Die Warnleuchte ausschalten"], 0, "Ungewollte Beschleunigung muss sicher verhindert werden."),
   mc("Wer legt fest, was der sichere Zustand ist?", ["Die Sicherheitsanalyse", "Der Fahrer", "Die Werkstatt", "Der Bus"], 0, "Gefährdungs- und Risikoanalyse nach ISO 26262 bestimmen die Sicherheitsziele."),
   mc("Was bedeutet Limp Home?", ["Eingeschränktes Weiterfahren nach Fehler", "Automatisches Einparken", "Fahrt in die Werkstatt per App", "Motorstart per Fernbedienung"], 0, "Der Notlauf erlaubt sicheres Erreichen eines Ziels mit reduzierter Leistung.")]),
 L("ecu.m3.l3", "Programmiermodus und Bootloader", 6, [
  "Zum Aktualisieren der Software wechselt das Steuergerät in einen eigenen Zustand: den Programmiermodus. Dafür ist ein Bootloader zuständig, ein kleines, eigenständiges Programm, das beim Start entscheidet, ob die Anwendung läuft oder neue Software geladen wird.",
  "## Der typische Ablauf über UDS",
  "Ein Tester wechselt per Diagnose in die programmierende Sitzung (UDS-Dienst 0x10, Sitzung 0x02), entsperrt das Steuergerät mit SecurityAccess (0x27), löscht den Speicher über RoutineControl (0x31), überträgt die Daten mit RequestDownload (0x34), TransferData (0x36) und RequestTransferExit (0x37), prüft das Ergebnis und setzt das Steuergerät zurück (ECUReset, 0x11).",
  "## Sicherheit",
  "Nur signierte Software darf geladen werden. Secure Boot prüft beim Start, ob der Code unverändert ist. Das schützt vor Manipulation, etwa am Abgasverhalten, und ist durch Vorschriften wie UN R155 und R156 für neue Fahrzeuge vorgeschrieben.",
  "## Wenn etwas schiefgeht",
  "Bricht das Flashen ab, bleibt der Bootloader erhalten. Das Steuergerät startet im Programmiermodus und kann erneut beschrieben werden."],
  ["Bootloader entscheidet: Anwendung starten oder neu programmieren.", "UDS-Ablauf: 0x10 02 → 0x27 → 0x31 → 0x34/0x36/0x37 → 0x11.", "Nur signierte Software; Secure Boot prüft beim Start."],
  [S_UDS, {"n": "UNECE: UN-Regelungen R155 (Cyber Security) und R156 (Software Update)", "u": "https://unece.org/transport/vehicle-regulations-wp29/standards/addenda-1958-agreement-regulations-141-160"}],
  [card("Bootloader", "Kleines Startprogramm, das die Anwendung startet oder neue Software lädt."),
   card("UDS 0x10 02", "DiagnosticSessionControl: Wechsel in die programmierende Sitzung."),
   card("UDS 0x27", "SecurityAccess: Entsperren geschützter Funktionen per Schlüsselaustausch."),
   card("UDS 0x34 / 0x36 / 0x37", "RequestDownload, TransferData, RequestTransferExit: Datenübertragung beim Flashen."),
   card("Secure Boot", "Prüfung beim Start, ob die Software unverändert und signiert ist.")],
  [order("Ordne die UDS-Schritte beim Flashen.", ["Programmiersitzung starten (0x10 02)", "Entsperren (0x27)", "Speicher löschen (0x31)", "Daten übertragen (0x34, 0x36, 0x37)", "Steuergerät zurücksetzen (0x11)"], "So läuft ein typischer Programmiervorgang ab."),
   mc("Was bleibt erhalten, wenn ein Flashvorgang abbricht?", ["Der Bootloader", "Die neue Anwendung", "Der Fehlerspeicher des Testers", "Die Busverbindung"], 0, "Der Bootloader ist separat geschützt und ermöglicht einen neuen Versuch."),
   mc("Welcher UDS-Dienst entsperrt geschützte Funktionen?", ["SecurityAccess (0x27)", "ReadDataByIdentifier (0x22)", "TesterPresent (0x3E)", "ClearDiagnosticInformation (0x14)"], 0, "SecurityAccess nutzt einen Seed-Key-Austausch."),
   mc("Wozu dient Secure Boot?", ["Nur unveränderte, signierte Software startet", "Der Motor startet schneller", "Der Fehlerspeicher wird gesichert", "Die Batterie wird geschont"], 0, "Manipulierte Software wird erkannt und nicht ausgeführt.")])
]}

M4 = {"id": "ecu.m4", "level": 2, "title": "EPM: Kurbel- und Nockenwellenposition", "desc": "Wie das Steuergerät jederzeit weiß, wo jeder Kolben steht: Geberrad, Synchronisation, Phase und Winkeluhr.", "lessons": [
 L("ecu.m4.l1", "Geberrad und Kurbelwellensensor", 7, [
  "Damit Einspritzung und Zündung im richtigen Moment passieren, muss das Steuergerät den Kurbelwinkel kennen, auf ein Grad genau und schneller als der Motor dreht. Dieses Positionsmanagement wird oft EPM (Engine Position Management) genannt.",
  "## Das Geberrad 60-2",
  "Auf der Kurbelwelle sitzt ein Zahnrad mit Platz für 60 Zähne, von denen 2 fehlen. Die 58 vorhandenen Zähne liegen also im Abstand von 6 Grad. Die Lücke markiert eine feste Bezugsposition.",
  "## Der Sensor",
  "Ein Sensor tastet die Zähne ab. Ältere Systeme nutzen induktive Sensoren, deren Signal mit der Drehzahl stärker wird. Heute sind aktive Sensoren (Hall- oder magnetoresistiv) verbreitet: Sie liefern saubere Rechteckflanken schon bei sehr kleiner Drehzahl, teils sogar mit Erkennung der Drehrichtung, was beim Start-Stopp-Betrieb wichtig ist.",
  "## Drehzahl aus Zahnzeiten",
  "Die Zeit zwischen zwei Zahnflanken ergibt die Drehzahl: Bei 6 Grad pro Zahn und 1 ms Zahnzeit dreht die Welle 6 Grad pro Millisekunde, das sind 1.000 Umdrehungen pro Minute.",
  "Sieh dir unten an, wie Rad und Signal zusammenhängen."],
  ["EPM: Kurbelwinkel jederzeit genau kennen.", "60-2-Geberrad: 58 Zähne à 6°, Lücke als Bezug.", "Drehzahl = Winkel pro Zeit aus den Zahnzeiten."],
  [S_REIF, S_GTM],
  [card("EPM (Engine Position Management)", "Funktion, die aus Kurbel- und Nockenwellensignalen die genaue Motorposition bestimmt."),
   card("Geberrad 60-2", "Zahnrad mit 60 Teilungen, davon 2 Zähne fehlend; 6° pro Zahn, Lücke als Bezugsmarke."),
   card("Aktiver Drehzahlsensor", "Hall- oder magnetoresistiver Sensor mit eigener Versorgung, liefert Rechtecksignale schon bei sehr niedriger Drehzahl."),
   card("Zahnzeit", "Zeit zwischen zwei Zahnflanken; daraus berechnet sich die Drehzahl.")],
  [num("Wie viele Grad Kurbelwinkel liegen bei einem 60-2-Geberrad zwischen zwei Zähnen?", 6, "°", 0, "360° ÷ 60 Teilungen = 6°."),
   num("Die Zahnzeit beträgt 0,5 ms. Wie hoch ist die Drehzahl in 1/min?", 2000, "1/min", 1, "6° pro 0,5 ms = 12° pro ms = 12.000° pro s = 33,3 U/s = 2.000 1/min."),
   mc("Warum sind aktive Sensoren beim Start-Stopp-Betrieb vorteilhaft?", ["Saubere Signale schon bei sehr kleiner Drehzahl", "Sie brauchen keine Versorgung", "Sie sind immer günstiger", "Sie messen die Temperatur mit"], 0, "Induktive Sensoren liefern bei Kriechdrehzahl kaum Signal; manche aktive erkennen auch die Drehrichtung."),
   mc("Wozu dient die Zahnlücke?", ["Als feste Bezugsposition", "Zur Kühlung des Rades", "Um Gewicht zu sparen", "Damit der Sensor ruht"], 0, "Nur die Lücke unterscheidet eine Stelle eindeutig von allen anderen.")],
  figs=[{"after": 7, "w": "crank", "cap": "Geberrad 60-2 und Sensorsignal: Die lange Pause ist die Lücke."}]),
 L("ecu.m4.l2", "Synchronisation und Phase", 7, [
  "Beim Start weiß das Steuergerät noch nicht, wo der Motor steht. Es muss sich synchronisieren.",
  "## Die Lücke finden",
  "Die Software vergleicht aufeinanderfolgende Zahnzeiten. An der Lücke fehlen zwei Zähne, die Zeit ist dort etwa dreimal so lang wie bei einem normalen Zahn. Ein typischer Test: Ist eine Zahnzeit deutlich länger als die vorige und die nächste wieder normal, war es die Lücke. Danach zählt die Software die Zähne ab und kennt die Kurbelposition.",
  "## Warum der Nockenwellensensor nötig ist",
  "Ein Viertaktmotor braucht für einen Arbeitszyklus zwei Kurbelwellenumdrehungen, also 720 Grad. Die Kurbelwelle allein sagt nicht, ob ein Zylinder im Verdichtungs- oder im Ausstoßtakt ist. Die Nockenwelle dreht nur halb so schnell; ihr Sensor liefert die Phaseninformation. Erst Kurbelwelle plus Nockenwelle ergeben eine eindeutige Position im 720-Grad-Zyklus.",
  "## Schnellstart",
  "Damit der Motor rasch anspringt, nutzen moderne Systeme speziell geformte Nockenwellen-Geberräder und gespeicherte Stoppositionen, um möglichst früh synchron zu sein.",
  "## Synchronisationsverlust",
  "Passen gezählte Zähne und Lücke nicht mehr zusammen, etwa durch Störimpulse, verliert die Software die Synchronisation, unterdrückt Einspritzung und Zündung kurz und synchronisiert neu. Ein solches Ereignis wird diagnostiziert."],
  ["Synchronisation: Lücke über das Zahnzeit-Verhältnis finden, dann Zähne zählen.", "720° pro Arbeitsspiel: Nockenwelle liefert die Phase.", "Synchronisationsverlust → Einspritzung und Zündung kurz aus, neu synchronisieren."],
  [S_REIF, S_GTM],
  [card("Synchronisation", "Bestimmung der absoluten Kurbelposition, z. B. durch Erkennen der Zahnlücke."),
   card("Phase (Nockenwelle)", "Information, in welcher der beiden Kurbelwellenumdrehungen eines Arbeitsspiels sich der Motor befindet."),
   card("720° Kurbelwinkel", "Ein vollständiges Arbeitsspiel eines Viertaktmotors (zwei Kurbelwellenumdrehungen).")],
  [mc("Warum reicht der Kurbelwellensensor allein beim Viertakter nicht für die Einspritzung?", ["Er unterscheidet die zwei Umdrehungen eines Arbeitsspiels nicht", "Er ist zu ungenau", "Er misst nur Temperatur", "Er funktioniert erst ab 3.000 1/min"], 0, "Ohne Nockenwelle bleibt eine 360°-Mehrdeutigkeit."),
   num("Wie lang ist die Zahnzeit an der Lücke ungefähr im Vergleich zu einem normalen Zahn (Faktor)?", 3, "", 0, "Zwei fehlende Zähne: Die Zeit reicht über drei Teilungen."),
   mc("Was passiert bei Synchronisationsverlust typischerweise?", ["Einspritzung und Zündung kurz aus, neu synchronisieren", "Der Motor beschleunigt", "Der Fehlerspeicher wird gelöscht", "Die Nockenwelle wird verstellt"], 0, "Ohne sichere Position darf nicht eingespritzt oder gezündet werden."),
   num("Wie viel Grad Kurbelwinkel umfasst ein Arbeitsspiel eines Viertaktmotors?", 720, "°", 0, "Zwei Umdrehungen à 360°.")]),
 L("ecu.m4.l3", "Winkeluhr und winkelsynchrone Aufgaben", 6, [
  "Zwischen zwei Zähnen vergehen bei hoher Drehzahl nur Mikrosekunden, und trotzdem müssen Zündung und Einspritzung auf Bruchteile eines Grads genau erfolgen. Dafür rechnet das Steuergerät eine fein aufgelöste Winkeluhr.",
  "## Interpolation",
  "Aus den letzten Zahnzeiten wird vorhergesagt, wie schnell sich die Welle weiterdreht, und der Winkel zwischen den Zähnen fein unterteilt. In AURIX-Controllern kann das Generic Timer Module mit einer digitalen Phasenregelschleife (DPLL) diese Aufgabe in Hardware erledigen.",
  "## Winkelsynchrone Tasks",
  "Bestimmte Softwareteile laufen nicht nach Zeit, sondern nach Winkel, zum Beispiel einmal pro Zylinder-Segment. Bei 6.000 Umdrehungen pro Minute und sechs Zylindern sind das 300 Segmente pro Sekunde. Mit der Drehzahl wird es also immer enger für die Rechenzeit.",
  "## Dynamik",
  "Beim Beschleunigen oder bei Zündaussetzern schwankt die Drehzahl innerhalb einer Umdrehung. Gute Vorhersagen berücksichtigen das, sonst verschiebt sich der berechnete Winkel. Aus diesen feinen Schwankungen lässt sich übrigens auch auf Zündaussetzer schließen, eine wichtige OBD-Diagnose."],
  ["Winkeluhr: feine Interpolation zwischen den Zähnen.", "Winkelsynchrone Tasks laufen pro Segment; Rechenzeit wird bei hoher Drehzahl knapp.", "Drehzahlschwankungen dienen auch der Aussetzererkennung."],
  [S_GTM, S_AURIX, S_REIF],
  [card("Winkeluhr", "Fein aufgelöster, vorhergesagter Kurbelwinkel zwischen den Zahnflanken."),
   card("DPLL", "Digitale Phasenregelschleife; im GTM zur Erzeugung eines winkelproportionalen Takts genutzt."),
   card("Segment", "Kurbelwinkelbereich je Zylinder (z. B. 720° ÷ 6 = 120° beim Sechszylinder)."),
   card("Aussetzererkennung", "Diagnose von Verbrennungsaussetzern, u. a. über Drehzahlschwankungen der Kurbelwelle.")],
  [num("Wie viele Grad umfasst ein Segment beim Sechszylinder-Viertakter?", 120, "°", 0, "720° ÷ 6 = 120°."),
   num("Wie viele Segmente pro Sekunde fallen bei 6.000 1/min beim Sechszylinder an?", 300, "", 0, "100 Umdrehungen/s = 50 Arbeitsspiele/s, mal 6 Zylinder = 300."),
   mc("Wozu nutzt man die DPLL im GTM?", ["Winkeltakt zwischen den Zähnen erzeugen", "CAN-Nachrichten verschlüsseln", "Den Watchdog füttern", "Flash-Speicher löschen"], 0, "Sie liefert eine feine Winkelauflösung in Hardware."),
   mc("Woran kann man Zündaussetzer erkennen?", ["An Drehzahlschwankungen der Kurbelwelle", "Am Ladezustand der Batterie", "An der Außentemperatur", "An der Busauslastung"], 0, "Fehlt eine Verbrennung, verzögert die Kurbelwelle messbar.")])
]}
